-- Local candidate on 2511c927: registry projection and suspension of existing access.
-- No data migration, Auth/role/RLS/ACL change, account conversion or reactivation.
do $patch$
declare
  item jsonb; target oid; original text; revised text; definition text; metadata jsonb;
  patches jsonb := $manifest$[
  {
    "signature": "private.apply_shared_projection_columns(text,jsonb,uuid)",
    "before": "7e7a0bd09ba0dc5e44e27f93708a3c0f",
    "after": "8b50844ce9b96b1df5d6924e1886507e",
    "body": "\ndeclare\n  v_columns text;\n  v_excluded text[] := array['id','tenant_id','workspace_id','created_at','created_by','updated_at','updated_by'];\nbegin\n  if _table_name = 'clients' then\n    v_excluded := v_excluded || array[\n      'state_registration','municipal_registration','ie_indicator','cfop_client_type','tax_regime',\n      'accounting_code_client','accounting_code_supplier','budget_group_client','budget_group_supplier',\n      'payment_notes','taxes_enabled','tax_code','tax_description'\n    ];\n  elsif _table_name = 'drivers' then\n    v_excluded := v_excluded || array['current_vehicle_id','user_id'];\n  elsif _table_name = 'employees' then\n    v_excluded := v_excluded || array[\n      'manager_id','driver_id','user_id','branch','cost_center','hire_date','termination_date','version'\n    ];\n  elsif _table_name = 'vehicles' then\n    v_excluded := v_excluded || array['current_driver_id'];\n  else\n    raise exception 'unsupported_shared_projection_table' using errcode = '22023';\n  end if;\n\n  select string_agg(quote_ident(a.attname), ',' order by a.attnum)\n  into v_columns\n  from pg_catalog.pg_attribute a\n  join pg_catalog.pg_class c on c.oid = a.attrelid\n  join pg_catalog.pg_namespace n on n.oid = c.relnamespace\n  where n.nspname = 'public' and c.relname = _table_name\n    and a.attnum > 0 and not a.attisdropped\n    and not (a.attname = any(v_excluded));\n\n  execute format(\n    'update public.%1$I set (%2$s)=(select %2$s from jsonb_populate_record(null::public.%1$I,$1)) where id=$2',\n    _table_name, v_columns\n  ) using _source, _target_id;\nend;\n"
  },
  {
    "signature": "private.insert_shared_projection(text,jsonb,uuid,uuid)",
    "before": "3db01028e6671223606631f7117e9b95",
    "after": "3e4187d2b532cce30e3b2b82485e6c47",
    "body": "\ndeclare\n  v_id uuid := gen_random_uuid();\n  v_payload jsonb;\nbegin\n  if _table_name not in ('clients','drivers','employees','vehicles') then\n    raise exception 'unsupported_shared_projection_table' using errcode = '22023';\n  end if;\n\n  v_payload := _source || jsonb_build_object(\n    'id',v_id,'tenant_id',_tenant_id,'workspace_id',_workspace_id,\n    'created_at',now(),'updated_at',now(),'created_by',null,'updated_by',null\n  );\n  if _table_name = 'drivers' then\n    v_payload := v_payload || jsonb_build_object('current_vehicle_id',null,'user_id',null);\n  elsif _table_name = 'employees' then\n    v_payload := v_payload || jsonb_build_object('manager_id',null,'driver_id',null,'user_id',null);\n  elsif _table_name = 'vehicles' then\n    v_payload := v_payload || jsonb_build_object('current_driver_id',null);\n  end if;\n\n  execute format(\n    'insert into public.%1$I select (jsonb_populate_record(null::public.%1$I,$1)).*',\n    _table_name\n  ) using v_payload;\n  return v_id;\nend;\n"
  },
  {
    "signature": "private.sync_workspace_person_projection()",
    "before": "9dbdd1516632ffdcc7082fa6eae782da",
    "after": "b7630d4403a3d529cea2f71169ed802a",
    "body": "\ndeclare\n  v_kind text := case when tg_table_name='drivers' then 'driver' else 'employee' end;\n  v_person_id uuid;\n  v_identity text;\n  v_name text := new.name;\n  v_cpf text;\n  v_email text := new.email;\n  v_phone text := new.phone;\n  v_active boolean;\n  v_target record;\n  v_target_id uuid;\nbegin\n  if pg_trigger_depth() > 1 then return new; end if;\n  -- Vehicle assignment and audit timestamps are company-local, not shared-person edits.\n  if tg_table_name='drivers' and tg_op='UPDATE'\n    and (to_jsonb(new)-array['current_vehicle_id','updated_at','updated_by'])\n      is not distinct from (to_jsonb(old)-array['current_vehicle_id','updated_at','updated_by']) then\n    return new;\n  end if;\n  v_cpf := case when tg_table_name='drivers'\n    then coalesce(to_jsonb(new)->>'cpf',to_jsonb(new)->>'doc')\n    else to_jsonb(new)->>'doc_cpf' end;\n  v_active := case when tg_table_name='drivers'\n    then coalesce((to_jsonb(new)->>'active')::boolean,false)\n    else coalesce(to_jsonb(new)->>'status','inactive')<>'inactive' end;\n  v_identity := case when length(regexp_replace(coalesce(v_cpf,''),'[^0-9]','','g'))=11\n    then 'cpf:'||regexp_replace(v_cpf,'[^0-9]','','g') else v_kind||':'||new.id::text end;\n\n  if tg_table_name='drivers' then\n    select link.workspace_person_id into v_person_id from public.workspace_person_tenant_links link\n    where link.tenant_id=new.tenant_id and link.driver_id=new.id;\n  else\n    select link.workspace_person_id into v_person_id from public.workspace_person_tenant_links link\n    where link.tenant_id=new.tenant_id and link.employee_id=new.id;\n  end if;\n\n  if v_person_id is null then\n    insert into public.workspace_people(id,workspace_id,identity_key,name,cpf,email,phone,source_data,active,created_at,updated_at)\n    values(new.id,new.workspace_id,v_identity,v_name,v_cpf,v_email,v_phone,to_jsonb(new),v_active,new.created_at,new.updated_at)\n    on conflict(workspace_id,identity_key) do update set\n      name=excluded.name,cpf=excluded.cpf,email=excluded.email,phone=excluded.phone,\n      source_data=excluded.source_data,active=excluded.active,updated_at=excluded.updated_at\n    returning id into v_person_id;\n  else\n    update public.workspace_people set name=v_name,cpf=v_cpf,email=v_email,phone=v_phone,\n      source_data=to_jsonb(new),active=v_active,updated_at=new.updated_at where id=v_person_id;\n  end if;\n\n  if tg_table_name='drivers' then\n    insert into public.workspace_person_tenant_links(workspace_id,workspace_person_id,tenant_id,driver_id)\n    values(new.workspace_id,v_person_id,new.tenant_id,new.id) on conflict(tenant_id,driver_id) do nothing;\n  else\n    insert into public.workspace_person_tenant_links(workspace_id,workspace_person_id,tenant_id,employee_id)\n    values(new.workspace_id,v_person_id,new.tenant_id,new.id) on conflict(tenant_id,employee_id) do nothing;\n  end if;\n\n  for v_target in\n    select t.id tenant_id,\n      case when v_kind='driver' then link.driver_id else link.employee_id end projection_id\n    from public.tenants t\n    left join public.workspace_person_tenant_links link on link.workspace_person_id=v_person_id and link.tenant_id=t.id\n      and ((v_kind='driver' and link.driver_id is not null) or (v_kind='employee' and link.employee_id is not null))\n    where t.workspace_id=new.workspace_id and t.id<>new.tenant_id\n  loop\n    -- Registry projection never provisions or replaces account access.\n    if v_target.projection_id is null then\n      v_target_id := private.insert_shared_projection(tg_table_name,to_jsonb(new),v_target.tenant_id,new.workspace_id);\n      if v_kind='driver' then\n        insert into public.workspace_person_tenant_links(workspace_id,workspace_person_id,tenant_id,driver_id)\n        values(new.workspace_id,v_person_id,v_target.tenant_id,v_target_id);\n      else\n        insert into public.workspace_person_tenant_links(workspace_id,workspace_person_id,tenant_id,employee_id)\n        values(new.workspace_id,v_person_id,v_target.tenant_id,v_target_id);\n      end if;\n    else\n      perform private.apply_shared_projection_columns(tg_table_name,to_jsonb(new),v_target.projection_id);\n    end if;\n  end loop;\n  return new;\nend;\n"
  },
  {
    "signature": "private.sync_employee_from_tenant_membership_v1()",
    "before": "3b05db0b8a1eb30ca63e13047c593118",
    "after": "89a57e095f3af86c2f4bfb5488b0cfac",
    "body": "\ndeclare\n  v_workspace_id uuid;\n  v_tenant_id uuid;\n  v_user_id uuid;\n  v_role public.app_role;\n  v_active boolean := false;\n  v_was_employee boolean := false;\n  v_is_employee boolean := false;\nbegin\n  if pg_catalog.pg_trigger_depth() > 1 then\n    if tg_op = 'DELETE' then return old; end if;\n    return new;\n  end if;\n\n  if tg_op = 'DELETE' then\n    v_tenant_id := old.tenant_id;\n    v_user_id := old.user_id;\n    v_role := old.role;\n    v_was_employee := old.role in ('owner', 'admin', 'operator', 'driver');\n  else\n    v_tenant_id := new.tenant_id;\n    v_user_id := new.user_id;\n    v_role := new.role;\n    v_active := new.active;\n    v_is_employee := new.role in ('owner', 'admin', 'operator', 'driver');\n    if tg_op = 'UPDATE' then\n      v_was_employee := old.role in ('owner', 'admin', 'operator', 'driver');\n    end if;\n  end if;\n\n  select tenant.workspace_id\n  into v_workspace_id\n  from public.tenants tenant\n  where tenant.id = v_tenant_id;\n\n  if v_workspace_id is null then\n    if tg_op = 'DELETE' then return old; end if;\n    return new;\n  end if;\n\n  -- Suspension only: update existing access; do not run an INSERT/UPSERT.\n  -- Reactivation/conversion/role changes keep their original account guards.\n  if tg_op='UPDATE' and old.role='driver' and new.role='driver'\n    and not new.active and new.user_id=old.user_id\n    and (to_jsonb(new)->>'tenant_id') is not distinct from (to_jsonb(old)->>'tenant_id')\n    and (to_jsonb(new)->>'workspace_id') is not distinct from (to_jsonb(old)->>'workspace_id') then\n    -- All account-scope inserts/updates already take SHARE on this same Auth row.\n    -- Upgrade without waiting to exclude new/moved memberships during suspension.\n    -- No Auth field is read into a payload or changed.\n    perform u.id from auth.users u where u.id=v_user_id for update nowait;\n    -- CAS may already hold one child row. Fail closed instead of lock inversion.\n    perform t.id from public.tenants t where t.workspace_id=v_workspace_id\n      order by t.id for share nowait;\n    perform m.id from public.tenant_memberships m join public.tenants t on t.id=m.tenant_id\n      where t.workspace_id=v_workspace_id and m.user_id=v_user_id\n      order by m.tenant_id,m.id for update of m nowait;\n    perform w.id from public.workspace_memberships w\n      where w.workspace_id=v_workspace_id and w.user_id=v_user_id for update nowait;\n    if exists(select 1 from public.tenant_memberships m join public.tenants t on t.id=m.tenant_id\n        where t.workspace_id=v_workspace_id and m.user_id=v_user_id and m.role<>'driver')\n      or exists(select 1 from public.workspace_memberships w where w.workspace_id=v_workspace_id\n        and w.user_id=v_user_id and w.role<>'driver') then\n      raise exception 'driver_suspension_mixed_operation_roles' using errcode='42501';\n    end if;\n    update public.workspace_memberships set active=false,updated_at=now()\n      where workspace_id=v_workspace_id and user_id=v_user_id and role='driver' and active;\n    update public.tenant_memberships m set active=false,updated_at=now()\n      from public.tenants t where t.id=m.tenant_id and t.workspace_id=v_workspace_id\n        and m.user_id=v_user_id and m.role='driver' and m.active;\n    return new;\n  end if;\n\n  if tg_op <> 'DELETE' and v_is_employee then\n    insert into public.workspace_memberships (workspace_id, user_id, role, active)\n    values (v_workspace_id, v_user_id, v_role, v_active)\n    on conflict (workspace_id, user_id) do update\n    set role = excluded.role,\n        active = excluded.active,\n        updated_at = now();\n\n    insert into public.tenant_memberships (tenant_id, user_id, role, active)\n    select tenant.id, v_user_id, v_role, v_active\n    from public.tenants tenant\n    where tenant.workspace_id = v_workspace_id\n    order by tenant.id\n    on conflict (tenant_id, user_id) do update\n    set role = excluded.role,\n        active = excluded.active,\n        updated_at = now();\n  elsif v_was_employee then\n    update public.workspace_memberships\n    set active = false,\n        updated_at = now()\n    where workspace_id = v_workspace_id\n      and user_id = v_user_id;\n\n    update public.tenant_memberships membership\n    set active = false,\n        updated_at = now()\n    from public.tenants tenant\n    where tenant.id = membership.tenant_id\n      and tenant.workspace_id = v_workspace_id\n      and membership.user_id = v_user_id\n      and membership.role in ('owner', 'admin', 'operator', 'driver');\n  end if;\n\n  if tg_op = 'DELETE' then return old; end if;\n  return new;\nend;\n"
  },
  {
    "signature": "private.sync_employee_from_workspace_membership_v1()",
    "before": "e41ac02a0164e958e93a552d546dba65",
    "after": "5fb06f91e10ba2253f343c9a189665d5",
    "body": "\ndeclare\n  v_workspace_id uuid;\n  v_user_id uuid;\n  v_role public.app_role;\n  v_active boolean := false;\n  v_was_employee boolean := false;\n  v_is_employee boolean := false;\nbegin\n  if pg_catalog.pg_trigger_depth() > 1 then\n    if tg_op = 'DELETE' then return old; end if;\n    return new;\n  end if;\n\n  if tg_op = 'DELETE' then\n    v_workspace_id := old.workspace_id;\n    v_user_id := old.user_id;\n    v_role := old.role;\n    v_was_employee := old.role in ('owner', 'admin', 'operator', 'driver');\n  else\n    v_workspace_id := new.workspace_id;\n    v_user_id := new.user_id;\n    v_role := new.role;\n    v_active := new.active;\n    v_is_employee := new.role in ('owner', 'admin', 'operator', 'driver');\n    if tg_op = 'UPDATE' then\n      v_was_employee := old.role in ('owner', 'admin', 'operator', 'driver');\n    end if;\n  end if;\n\n  -- Suspension only: update existing access; do not run an INSERT/UPSERT.\n  -- Reactivation/conversion/role changes keep their original account guards.\n  if tg_op='UPDATE' and old.role='driver' and new.role='driver'\n    and not new.active and new.user_id=old.user_id\n    and (to_jsonb(new)->>'tenant_id') is not distinct from (to_jsonb(old)->>'tenant_id')\n    and (to_jsonb(new)->>'workspace_id') is not distinct from (to_jsonb(old)->>'workspace_id') then\n    -- All account-scope inserts/updates already take SHARE on this same Auth row.\n    -- Upgrade without waiting to exclude new/moved memberships during suspension.\n    -- No Auth field is read into a payload or changed.\n    perform u.id from auth.users u where u.id=v_user_id for update nowait;\n    -- CAS may already hold one child row. Fail closed instead of lock inversion.\n    perform t.id from public.tenants t where t.workspace_id=v_workspace_id\n      order by t.id for share nowait;\n    perform m.id from public.tenant_memberships m join public.tenants t on t.id=m.tenant_id\n      where t.workspace_id=v_workspace_id and m.user_id=v_user_id\n      order by m.tenant_id,m.id for update of m nowait;\n    perform w.id from public.workspace_memberships w\n      where w.workspace_id=v_workspace_id and w.user_id=v_user_id for update nowait;\n    if exists(select 1 from public.tenant_memberships m join public.tenants t on t.id=m.tenant_id\n        where t.workspace_id=v_workspace_id and m.user_id=v_user_id and m.role<>'driver')\n      or exists(select 1 from public.workspace_memberships w where w.workspace_id=v_workspace_id\n        and w.user_id=v_user_id and w.role<>'driver') then\n      raise exception 'driver_suspension_mixed_operation_roles' using errcode='42501';\n    end if;\n    update public.workspace_memberships set active=false,updated_at=now()\n      where workspace_id=v_workspace_id and user_id=v_user_id and role='driver' and active;\n    update public.tenant_memberships m set active=false,updated_at=now()\n      from public.tenants t where t.id=m.tenant_id and t.workspace_id=v_workspace_id\n        and m.user_id=v_user_id and m.role='driver' and m.active;\n    return new;\n  end if;\n\n  if tg_op <> 'DELETE' and v_is_employee then\n    insert into public.tenant_memberships (tenant_id, user_id, role, active)\n    select tenant.id, v_user_id, v_role, v_active\n    from public.tenants tenant\n    where tenant.workspace_id = v_workspace_id\n    order by tenant.id\n    on conflict (tenant_id, user_id) do update\n    set role = excluded.role,\n        active = excluded.active,\n        updated_at = now();\n  elsif v_was_employee then\n    update public.tenant_memberships membership\n    set active = false,\n        updated_at = now()\n    from public.tenants tenant\n    where tenant.id = membership.tenant_id\n      and tenant.workspace_id = v_workspace_id\n      and membership.user_id = v_user_id\n      and membership.role in ('owner', 'admin', 'operator', 'driver');\n  end if;\n\n  if tg_op = 'DELETE' then return old; end if;\n  return new;\nend;\n"
  }
]$manifest$::jsonb;
begin
  if not exists(select 1 from pg_proc where oid=to_regprocedure('private.guard_driver_account_scope_v1()')
      and md5(prosrc)='ffb3e58ae5f4915a997cf1b26fe587ad' and prosecdef and proowner='postgres'::regrole)
    or not exists(select 1 from pg_trigger where tgrelid='public.tenant_memberships'::regclass
      and tgname='guard_driver_tenant_scope' and tgfoid=to_regprocedure('private.guard_driver_account_scope_v1()')
      and tgenabled='O' and tgtype=23 and tgqual is null and tgattr=''::int2vector)
    or not exists(select 1 from pg_trigger where tgrelid='public.workspace_memberships'::regclass
      and tgname='guard_driver_workspace_scope' and tgfoid=to_regprocedure('private.guard_driver_account_scope_v1()')
      and tgenabled='O' and tgtype=23 and tgqual is null and tgattr=''::int2vector) then
    raise exception 'driver_registry_suspension_scope_guard_changed';
  end if;
  for item in select value from jsonb_array_elements(patches) loop
    target:=to_regprocedure(item->>'signature');
    if target is null or not exists(select 1 from pg_proc p where p.oid=target
      and p.proowner='postgres'::regrole and p.prosecdef
      and p.proconfig=array['search_path=""']::text[]
      and md5(prosrc) in(item->>'before',item->>'after')) then
      raise exception 'driver_registry_suspension_predecessor_changed: %',item->>'signature';
    end if;
    if md5(item->>'body')<>item->>'after' then raise exception 'driver_registry_suspension_patch_changed';end if;
  end loop;
  for item in select value from jsonb_array_elements(patches) loop
    target:=to_regprocedure(item->>'signature');
    select prosrc,pg_get_functiondef(oid),to_jsonb(p)-'prosrc' into original,definition,metadata from pg_proc p where p.oid=target;
    if md5(original)=item->>'after' then continue;end if;
    revised:=item->>'body';execute replace(definition,original,revised);
    if (select to_jsonb(p)-'prosrc' from pg_proc p where p.oid=target) is distinct from metadata
      or (select md5(prosrc) from pg_proc where oid=target)<>item->>'after' then
      raise exception 'driver_registry_suspension_metadata_changed: %',item->>'signature';
    end if;
  end loop;
end;
$patch$;
